const { PDFDocument, StandardFonts } = require('pdf-lib');
const fs = require('fs');

(async () => {
  const doc = await PDFDocument.create();
  const font = await doc.embedFont(StandardFonts.Helvetica);
  const page = doc.addPage([595, 842]);

  // Labels
  page.drawText('Name:', { x: 50, y: 750, size: 14, font });
  page.drawText('Date:', { x: 50, y: 690, size: 14, font });
  page.drawText('Consent:', { x: 50, y: 630, size: 14, font });

  const form = doc.getForm();

  // Text field: name
  const nameField = form.createTextField('name');
  nameField.addToPage(page, { x: 130, y: 740, width: 300, height: 28, fontSize: 12 });

  // Text field: date
  const dateField = form.createTextField('date');
  dateField.addToPage(page, { x: 130, y: 680, width: 300, height: 28, fontSize: 12 });

  // Checkbox: consent
  const consentField = form.createCheckBox('consent');
  consentField.addToPage(page, { x: 130, y: 625, width: 24, height: 24 });

  const bytes = await doc.save();
  fs.writeFileSync('/workspace/blank.pdf', bytes);
  console.log('blank.pdf created');
})().catch(e => { console.error(e.stack); process.exit(1); });

const { PDFDocument } = require('pdf-lib');
const fs = require('fs');

(async () => {
  // Reload blank.pdf from disk
  const blankBytes = fs.readFileSync('/workspace/blank.pdf');
  const doc = await PDFDocument.load(blankBytes);
  const form = doc.getForm();

  // Fill text fields
  const nameField = form.getTextField('name');
  nameField.setText('TEST USER');

  const dateField = form.getTextField('date');
  dateField.setText('2026-09-07');

  // Check the consent checkbox
  const consentField = form.getCheckBox('consent');
  consentField.check();

  // Save WITHOUT flattening — fields remain editable
  const filledBytes = await doc.save();
  fs.writeFileSync('/workspace/filled.pdf', filledBytes);
  console.log('filled.pdf saved');
})().catch(e => { console.error(e.stack); process.exit(1); });

const { PDFDocument } = require('pdf-lib');
const fs = require('fs');

(async () => {
  // Re-open filled.pdf from disk for verification
  const filledBytes = fs.readFileSync('/workspace/filled.pdf');
  const doc = await PDFDocument.load(filledBytes);
  const form = doc.getForm();

  const nameVal = form.getTextField('name').getText();
  const dateVal = form.getTextField('date').getText();
  const consentVal = form.getCheckBox('consent').isChecked();

  console.log('=== Field Verification ===');
  console.log('name:', JSON.stringify(nameVal));
  console.log('date:', JSON.stringify(dateVal));
  console.log('consent:', consentVal);

  let ok = true;
  if (nameVal !== 'TEST USER') { console.error('FAIL: name mismatch'); ok = false; }
  if (dateVal !== '2026-09-07') { console.error('FAIL: date mismatch'); ok = false; }
  if (consentVal !== true) { console.error('FAIL: consent not checked'); ok = false; }

  if (ok) {
    console.log('ALL FIELDS VERIFIED OK');
  } else {
    process.exit(1);
  }
})().catch(e => { console.error(e.stack); process.exit(1); });
